#pragma once

// Runtime support for code generated by tools/recomp. Generated functions take
// a Ctx holding the arm64 register file. Memory operands are host addresses:
// the game image is loaded at `g_imageBase` and its internal pointers are
// rebased, so guest pointers and host pointers are the same thing.

#include <cmath>
#include <cstdint>
#include <cstring>
#include <limits>

namespace recomp
{
    struct alignas(16) V128
    {
        union
        {
            uint8_t u8[16];
            uint16_t u16[8];
            uint32_t u32[4];
            uint64_t u64[2];
            int8_t s8[16];
            int16_t s16[8];
            int32_t s32[4];
            int64_t s64[2];
            float f32[4];
            double f64[2];
        };
    };

    struct Ctx
    {
        uint64_t x[31];  // x0..x30 (x29 = fp, x30 = lr)
        uint64_t sp;
        V128 v[32];
        uint8_t n, z, c, vf;  // NZCV
    };

    using Function = void (*)(Ctx&);

    struct FunctionEntry
    {
        uint64_t address;  // guest address in the original image
        Function function;
    };

    // Emitted by the recompiler (recomp_table.cpp), sorted by address.
    extern const FunctionEntry kFunctionTable[];
    extern const size_t kFunctionCount;
    // A second set translated on its own (arm64_recomp.py --extra-table);
    // calls between the sets go through CallImport.
    extern const FunctionEntry kExtraFunctionTable[];
    extern const size_t kExtraFunctionCount;

    extern uint64_t g_imageBase;
    extern uint64_t g_imageSize;

    // Calls a host function whose signature the runtime knows (an engine
    // icall); returns false when it does not. Set by the platform glue.
    extern bool (*g_typedNativeCall)(Ctx& c, uint64_t target);

    // Provided by the runtime: calls outside the recompiled set (libil2cpp
    // helpers, libc stubs) and indirect branches to computed addresses.
    void CallImport(Ctx& c, uint64_t guestAddress);
    void RegisterImport(uint64_t guestAddress, Function handler);
    Function FindFunction(uint64_t guestAddress);
    void CallIndirect(Ctx& c, uint64_t hostAddress);
    [[noreturn]] void Trap(Ctx& c, uint64_t guestAddress, uint32_t code);
    [[noreturn]] void Unimplemented(Ctx& c, uint64_t guestAddress, const char* instruction);

    template <typename T>
    inline T Load(uint64_t address)
    {
        T value;
        memcpy(&value, reinterpret_cast<const void*>(address), sizeof(T));
        return value;
    }

    template <typename T>
    inline void Store(uint64_t address, T value)
    {
        memcpy(reinterpret_cast<void*>(address), &value, sizeof(T));
    }

    // Writing a scalar FP/SIMD register clears the rest of the vector.
    inline void SetS(V128& v, float value) { v = V128{}; v.f32[0] = value; }
    inline void SetD(V128& v, double value) { v = V128{}; v.f64[0] = value; }
    inline void SetS32(V128& v, uint32_t value) { v = V128{}; v.u32[0] = value; }
    inline void SetD64(V128& v, uint64_t value) { v = V128{}; v.u64[0] = value; }

    inline void FlagsSub64(Ctx& c, uint64_t a, uint64_t b)
    {
        uint64_t r = a - b;
        c.n = uint8_t(r >> 63);
        c.z = r == 0;
        c.c = a >= b;
        c.vf = uint8_t(((a ^ b) & (a ^ r)) >> 63);
    }

    inline void FlagsSub32(Ctx& c, uint32_t a, uint32_t b)
    {
        uint32_t r = a - b;
        c.n = uint8_t(r >> 31);
        c.z = r == 0;
        c.c = a >= b;
        c.vf = uint8_t(((a ^ b) & (a ^ r)) >> 31);
    }

    inline void FlagsAdd64(Ctx& c, uint64_t a, uint64_t b)
    {
        uint64_t r = a + b;
        c.n = uint8_t(r >> 63);
        c.z = r == 0;
        c.c = r < a;
        c.vf = uint8_t((~(a ^ b) & (a ^ r)) >> 63);
    }

    inline void FlagsAdd32(Ctx& c, uint32_t a, uint32_t b)
    {
        uint32_t r = a + b;
        c.n = uint8_t(r >> 31);
        c.z = r == 0;
        c.c = r < a;
        c.vf = uint8_t((~(a ^ b) & (a ^ r)) >> 31);
    }

    // adcs/sbcs (sbcs passes ~b): flags of a + b + carry
    template <typename T>
    inline void FlagsAdcT(Ctx& c, T a, T b, T carry)
    {
        constexpr int top = sizeof(T) * 8 - 1;
        T r = T(a + b + carry);
        c.n = uint8_t(r >> top);
        c.z = r == 0;
        c.c = carry ? r <= a : r < a;
        c.vf = uint8_t(T(~(a ^ b) & (a ^ r)) >> top);
    }
    inline void FlagsAdc64(Ctx& c, uint64_t a, uint64_t b, uint64_t carry) { FlagsAdcT<uint64_t>(c, a, b, carry); }
    inline void FlagsAdc32(Ctx& c, uint32_t a, uint32_t b, uint32_t carry) { FlagsAdcT<uint32_t>(c, a, b, carry); }

    // Logical ops (ands/tst/bics) set N and Z, clear C and V.
    inline void FlagsLogic64(Ctx& c, uint64_t r) { c.n = uint8_t(r >> 63); c.z = r == 0; c.c = 0; c.vf = 0; }
    inline void FlagsLogic32(Ctx& c, uint32_t r) { c.n = uint8_t(r >> 31); c.z = r == 0; c.c = 0; c.vf = 0; }

    inline void SetNzcv(Ctx& c, uint32_t nzcv)
    {
        c.n = (nzcv >> 3) & 1;
        c.z = (nzcv >> 2) & 1;
        c.c = (nzcv >> 1) & 1;
        c.vf = nzcv & 1;
    }

    template <typename F>
    inline void FlagsFcmp(Ctx& c, F a, F b)
    {
        if (std::isnan(a) || std::isnan(b)) SetNzcv(c, 0b0011);
        else if (a == b) SetNzcv(c, 0b0110);
        else if (a < b) SetNzcv(c, 0b1000);
        else SetNzcv(c, 0b0010);
    }

    // FP -> integer conversions saturate and map NaN to 0, unlike C++ casts.
    template <typename I, typename F>
    inline I FcvtSat(F value)
    {
        if (std::isnan(value)) return 0;
        if (value <= F(std::numeric_limits<I>::min())) return std::numeric_limits<I>::min();
        if (value >= F(std::numeric_limits<I>::max())) return std::numeric_limits<I>::max();
        return I(value);
    }

    // AArch64 fmax/fmin propagate NaN (unlike std::fmax).
    template <typename F> inline F Fmax(F a, F b)
    {
        if (std::isnan(a) || std::isnan(b)) return std::numeric_limits<F>::quiet_NaN();
        if (a == 0 && b == 0) return std::signbit(a) ? b : a;
        return a > b ? a : b;
    }

    template <typename F> inline F Fmin(F a, F b)
    {
        if (std::isnan(a) || std::isnan(b)) return std::numeric_limits<F>::quiet_NaN();
        if (a == 0 && b == 0) return std::signbit(a) ? a : b;
        return a < b ? a : b;
    }

    // fmaxnm/fminnm: a quiet NaN loses to a number; -0 < +0.
    inline bool IsSignalingNan(float v) { uint32_t u; memcpy(&u, &v, 4); return std::isnan(v) && !(u & 0x400000u); }
    inline bool IsSignalingNan(double v) { uint64_t u; memcpy(&u, &v, 8); return std::isnan(v) && !(u & 0x8000000000000ull); }
    inline float Quiet(float v) { uint32_t u; memcpy(&u, &v, 4); u |= 0x400000u; memcpy(&v, &u, 4); return v; }
    inline double Quiet(double v) { uint64_t u; memcpy(&u, &v, 8); u |= 0x8000000000000ull; memcpy(&v, &u, 8); return v; }

    template <typename F> inline F Fmaxnm(F a, F b)
    {
        // a signaling NaN operand gives its quieted self; a single quiet NaN
        // is ignored (IEEE 754-2008 maxNum/minNum, as arm64 implements them)
        if (IsSignalingNan(a)) return Quiet(a);
        if (IsSignalingNan(b)) return Quiet(b);
        if (std::isnan(a)) return std::isnan(b) ? a : b;
        if (std::isnan(b)) return a;
        return Fmax(a, b);
    }

    inline uint32_t Popcount64(uint64_t v)
    {
        uint32_t n = 0;
        for (; v; v &= v - 1)
            n++;
        return n;
    }

    template <typename F> inline F Fminnm(F a, F b)
    {
        // a signaling NaN operand gives its quieted self; a single quiet NaN
        // is ignored (IEEE 754-2008 maxNum/minNum, as arm64 implements them)
        if (IsSignalingNan(a)) return Quiet(a);
        if (IsSignalingNan(b)) return Quiet(b);
        if (std::isnan(a)) return std::isnan(b) ? a : b;
        if (std::isnan(b)) return a;
        return Fmin(a, b);
    }

    inline uint64_t Ror64(uint64_t v, unsigned s) { s &= 63; return s ? (v >> s) | (v << (64 - s)) : v; }
    inline uint32_t Ror32(uint32_t v, unsigned s) { s &= 31; return s ? (v >> s) | (v << (32 - s)) : v; }

    inline int64_t Sdiv64(int64_t a, int64_t b)
    {
        if (b == 0) return 0;
        if (a == std::numeric_limits<int64_t>::min() && b == -1) return a;
        return a / b;
    }

    inline int32_t Sdiv32(int32_t a, int32_t b)
    {
        if (b == 0) return 0;
        if (a == std::numeric_limits<int32_t>::min() && b == -1) return a;
        return a / b;
    }

    inline uint64_t Udiv64(uint64_t a, uint64_t b) { return b ? a / b : 0; }
    inline uint32_t Udiv32(uint32_t a, uint32_t b) { return b ? a / b : 0; }

    inline int64_t Smulh(int64_t a, int64_t b)
    {
#if defined(__SIZEOF_INT128__)
        return int64_t((__int128(a) * __int128(b)) >> 64);
#else
        int64_t high;
        _mul128(a, b, &high);
        return high;
#endif
    }

    inline uint64_t Umulh(uint64_t a, uint64_t b)
    {
#if defined(__SIZEOF_INT128__)
        return uint64_t((unsigned __int128)a * b >> 64);
#else
        uint64_t high;
        _umul128(a, b, &high);
        return high;
#endif
    }

    inline uint64_t Rbit64(uint64_t v)
    {
        uint64_t r = 0;
        for (int i = 0; i < 64; i++)
            r |= ((v >> i) & 1) << (63 - i);
        return r;
    }

    inline uint32_t Rbit32(uint32_t v)
    {
        uint32_t r = 0;
        for (int i = 0; i < 32; i++)
            r |= ((v >> i) & 1) << (31 - i);
        return r;
    }

    inline float BitsToF32(uint32_t v) { float f; memcpy(&f, &v, 4); return f; }
    inline double BitsToF64(uint64_t v) { double d; memcpy(&d, &v, 8); return d; }
    inline uint32_t F32ToBits(float f) { uint32_t v; memcpy(&v, &f, 4); return v; }
    inline uint64_t F64ToBits(double d) { uint64_t v; memcpy(&v, &d, 8); return v; }
}
